/*
 Import all product specific js
 */
import PageManager from './page-manager';
import Review from '../papathemes/eyeva/reviews'; // papathemes-eyeva edited
import collapsibleFactory from './common/collapsible';
import ProductDetails from '../papathemes/eyeva/product-details'; // papathemes-eyeva edited
import videoGallery from './product/video-gallery';
import { classifyForm } from './common/utils/form-utils';
import modalFactory from './global/modal';

export default class Product extends PageManager {
    constructor(context) {
        super(context);
        this.url = window.location.href;
        this.$reviewLink = $('[data-reveal-id="modal-review-form"]');
        this.$bulkPricingLink = $('[data-reveal-id="modal-bulk-pricing"]');
        this.reviewModal = modalFactory('#modal-review-form')[0];
    }

    onReady() {
        // Listen for foundation modal close events to sanitize URL after review.
        $(document).on('close.fndtn.reveal', () => {
            if (this.url.indexOf('#write_review') !== -1 && typeof window.history.replaceState === 'function') {
                window.history.replaceState(null, document.title, window.location.pathname);
            }
        });

        let validator;

        // Init collapsible
        collapsibleFactory();

        this.productDetails = new ProductDetails($('.productView'), this.context, window.BCData.product_attributes);
        this.productDetails.setProductVariant();

        // Handle mobile sticky bar add to cart button
        $('body').on('click', '#mobileAddToCartBtn', (event) => {
            event.preventDefault();
            const $form = $('.productView form[data-cart-item-add]');
            $form.submit();
        });

        // Sync quantity between mobile sticky bar and main form
        const $mainQty = $('.productView form[data-cart-item-add] [name="qty[]"]');
        const $mobileQty = $('#mobileStickyBar [name="mobile-qty"]');
        if ($mainQty.length && $mobileQty.length) {
            $mainQty.on('input change', () => {
                $mobileQty.val($mainQty.val());
            });
            $mobileQty.on('input change', () => {
                $mainQty.val($mobileQty.val());
            });
        }

        // Handle quantity change for mobile sticky bar
        $('body').on('click', '#mobileStickyBar [data-quantity-change] button', event => {
            event.preventDefault();
            const $target = $(event.currentTarget);
            const $input = $('#mobileStickyBar [name="mobile-qty"]');
            const quantityMin = parseInt($input.data('quantityMin'), 10) || 1;
            const quantityMax = parseInt($input.data('quantityMax'), 10) || 999;

            let qty = parseInt($input.val(), 10) || quantityMin;
            // If action is incrementing
            if ($target.data('action') === 'inc') {
                qty = Math.min(qty + 1, quantityMax);
            } else if (qty > quantityMin) {
                qty = Math.max(qty - 1, quantityMin);
            }

            // update input
            $input.val(qty);
            // sync to main form
            $mainQty.val(qty);
        });

        videoGallery();

        this.bulkPricingHandler();

        const $reviewForm = classifyForm('.writeReview-form');

        if ($reviewForm.length === 0) return;

        const review = new Review({ $reviewForm });

        $('body').on('click', '[data-reveal-id="modal-review-form"]', () => {
            validator = review.registerValidation(this.context);
            this.ariaDescribeReviewInputs($reviewForm);
        });

        $reviewForm.on('submit', () => {
            if (validator) {
                validator.performCheck();
                return validator.areAll('valid');
            }

            return false;
        });

        this.productReviewHandler();
    }

    ariaDescribeReviewInputs($form) {
        $form.find('[data-input]').each((_, input) => {
            const $input = $(input);
            const msgSpanId = `${$input.attr('name')}-msg`;

            $input.siblings('span').attr('id', msgSpanId);
            $input.attr('aria-describedby', msgSpanId);
        });
    }

    productReviewHandler() {
        if (this.url.indexOf('#write_review') !== -1) {
            this.$reviewLink.trigger('click');
        }
    }

    bulkPricingHandler() {
        if (this.url.indexOf('#bulk_pricing') !== -1) {
            this.$bulkPricingLink.trigger('click');
        }
    }
}
